<script setup>
import {computed} from 'vue';import {s,number,percent} from './store';defineProps({mobile:Boolean});
const columns=[{key:'group',label:'Khối'},{key:'name',label:'Đơn vị'},{key:'code',label:'Tracking'},{key:'target',label:'Mục tiêu',align:'right'},{key:'count',label:'Đăng ký',align:'right'},{key:'clevel',label:'C-Level',align:'right'},{key:'completion',label:'Hoàn thành',align:'right'}];
</script><template><section class="card"><h3>Mục tiêu & tracking</h3><div v-if="mobile" class="mobile-list"><article v-for="t in s.report.current.targets" :key="t.code"><strong>{{t.name}}</strong><p class="muted">{{t.group}} · {{t.code}}</p><p>{{number(t.count)}} / {{number(t.target)}} đăng ký · {{percent(t.completion)}}</p><p>C-Level: {{number(t.clevel)}}</p></article></div><div v-else class="report-table"><MDataTable :columns="columns" :rows="s.report.current.targets" row-key="code" :page-size="s.report.current.targets.length||20" :total="s.report.current.targets.length"><template #cell-target="{row}">{{number(row.target)}}</template><template #cell-count="{row}">{{number(row.count)}}</template><template #cell-clevel="{row}">{{number(row.clevel)}}</template><template #cell-completion="{row}">{{percent(row.completion)}}</template></MDataTable></div><MEmptyState v-if="!s.report.current.targets.length" type="initial" title="Chưa có mục tiêu chi tiết" /></section></template>
